    return ['read'=>'✓✓ Seen','delivered'=>'✓✓ Delivered','sent'=>'✓ Sent','accepted'=>'Accepted','failed'=>'Failed','unknown'=>'Status unavailable'][$state]??'Status unavailable';
}
function dashboardTextHtml($value){
    $parts=preg_split('~(https?://[^\s<>"\']+|www\.[^\s<>"\']+)~iu',(string)$value,-1,PREG_SPLIT_DELIM_CAPTURE);
    $html='';foreach($parts as $i=>$part){
        if($i%2===1){$tail='';$url=rtrim($part,".,!?;:)]}");$tail=mb_substr($part,mb_strlen($url));$href=stripos($url,'www.')===0?'https://'.$url:$url;$html.='<a class="message-link" href="'.h($href).'" target="_blank" rel="noopener noreferrer">'.h($url).'</a>'.h($tail);}
        else $html.=h($part);
    }
    return nl2br($html);
}
