    } catch (Throwable $e) {
        if($isAjax){http_response_code(422);header('Content-Type: application/json; charset=utf-8');echo json_encode(['ok'=>false,'error'=>$e->getMessage()],JSON_UNESCAPED_UNICODE);exit;}
        $_SESSION['dashboard_notice']='Action failed. '.$e->getMessage();
    }
    $location='owner.php?view='.rawurlencode($view);
    if($view==='conversations' && !empty($_POST['conv']))$location.='&conv='.(int)$_POST['conv'];
    header('Location: '.$location); exit;
}
