function csrf() { echo '<input type="hidden" name="csrf" value="'.h($_SESSION['csrf']).'">'; }
function emptyState($s) { echo '<div class="empty">'.h($s).'</div>'; }
function dashboardMessageImageSrc($m) {
 $meta=json_decode((string)($m['meta']??''),true);if(!is_array($meta) || ($meta['type']??'')!=='image')return '';
 if(!empty($meta['media_id']))return '?message_media='.(int)$m['id'];
 $when=strtotime((string)$m['created_at']);
 foreach(all('SELECT id,question,created_at FROM tickets WHERE conv_id=? ORDER BY id DESC LIMIT 20',[(int)$m['conv_id']]) as $ticket){
   list($mediaId)=mediaExtractMarker($ticket['question']);if($mediaId!=='' && abs(strtotime($ticket['created_at'])-$when)<=600)return '?ticket_media='.(int)$ticket['id'];
 }
 return '';
}
function ticketRecentContext($t,$limit=6) {
 $limit=max(1,min(10,(int)$limit));
 $rows=all('SELECT id,conv_id,direction,body,meta,created_at FROM messages WHERE conv_id=? AND created_at<=? ORDER BY id DESC LIMIT '.$limit,[(int)$t['conv_id'],$t['created_at']]);
 return array_reverse($rows);
}
function ticketCard($t) {
 list($ticketMedia,$cleanQuestion)=function_exists('mediaExtractMarker')?mediaExtractMarker($t['question']):['',$t['question']];
 $context=ticketRecentContext($t,6);
 $kind=['stock'=>'Stock check','info'=>'Information request','handoff'=>'Needs a person']; ?>
 <article class="ticket"><div class="ticket-top"><span class="badge <?= h($t['kind']) ?>"><?= h($kind[$t['kind']]) ?></span><span class="muted">#<?= (int)$t['id'] ?> · <?= h($t['created_at']) ?></span></div>
 <h3><?= h($t['customer'] ?: 'Customer') ?></h3><?php if ($t['product_name']): ?><p class="product"><?= h($t['product_name']) ?></p><?php endif; ?>
 <?php if($context): ?><section class="ticket-context"><div class="context-title">Recent conversation <span>Oldest to newest · <?= count($context) ?> messages</span></div><?php foreach($context as $message): $contextImage=dashboardMessageImageSrc($message); ?><div class="context-message <?= $message['direction']==='out'?'bot':'customer' ?>"><div><strong><?= $message['direction']==='out'?'Bot':'Customer' ?></strong><time><?= h(date('g:i A',strtotime($message['created_at']))) ?></time></div><?php if($contextImage): ?><img class="context-image" src="<?= h($contextImage) ?>" alt="Customer attachment" loading="lazy"><?php endif; ?><p><?= dashboardTextHtml(mb_substr($message['body'],0,700)) ?></p></div><?php endforeach; ?></section><?php endif; ?>
 <?php if($ticketMedia): ?><img class="customer-image" src="?ticket_media=<?= (int)$t['id'] ?>" alt="Customer attachment" loading="lazy"><?php endif; ?><div class="current-question-label">Ticket question</div><p class="question"><?= dashboardTextHtml($cleanQuestion) ?></p><div class="muted small"><?= $t['status']==='queued'?'Waiting to notify the owner':'Waiting for an owner response' ?></div>
 <form method="post"><?php csrf(); ?><input type="hidden" name="ticket" value="<?= (int)$t['id'] ?>">
 <?php if ($t['kind']==='info'): ?><label>Your answer<textarea name="answer" maxlength="3000" placeholder="Enter the correct information…"></textarea></label><label>Knowledge scope<select name="scope"><?php if ($t['product_id']): ?><option value="product">This product only</option><?php else: ?><option value="global">General store information</option><?php endif; ?></select></label><?php endif; ?>
 <div class="actions"><?php if ($t['kind']==='stock' && $t['product_id']): ?><button name="act" value="in">In stock · 3 days</button><button class="secondary" name="act" value="out">Out · 3 months</button><button class="secondary" name="act" value="permanent">Permanently out</button><?php elseif ($t['kind']==='info'): ?><button name="act" value="answer">Send & learn ↗</button><?php endif; ?><button class="secondary" name="act" value="takeover">Take over · pause bot</button><button class="quiet" name="act" value="close">Close ticket</button></div></form></article>
<?php }
