(function(){
 const conv=<?= (int)$cid ?>,stream=document.getElementById('chat-stream'),list=document.getElementById('conversation-list'),status=document.getElementById('live-status'),navUnread=document.getElementById('conversation-unread-total');
 if(!stream||!list)return;let last=0,busy=false;stream.querySelectorAll('[data-message-id]').forEach(x=>last=Math.max(last,Number(x.dataset.messageId)||0));
 const node=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e};
 function linkedParagraph(text){const p=node('p'),parts=String(text||'').split(/(https?:\/\/[^\s<>\"']+|www\.[^\s<>\"']+)/gi);parts.forEach((part,i)=>{if(i%2){const a=node('a','message-link',part);a.href=/^www\./i.test(part)?'https://'+part:part;a.target='_blank';a.rel='noopener noreferrer';p.appendChild(a)}else{part.split('\n').forEach((line,j)=>{if(j)p.appendChild(document.createElement('br'));p.appendChild(document.createTextNode(line))})}});return p}
 function feedback(box,m,csrf){const d=node('details','reply-feedback'),sum=node('summary','', '✎ Improve this reply'),f=document.createElement('form');f.method='post';
  [['act','reply_feedback'],['conv',String(conv)],['message_id',String(m.id)],['csrf',csrf]].forEach(v=>{const i=document.createElement('input');i.type='hidden';i.name=v[0];i.value=v[1];f.appendChild(i)});
  const ta=document.createElement('textarea');ta.name='preferred_reply';ta.rows=2;ta.maxLength=3000;ta.required=true;ta.placeholder='এই উত্তরটি কীভাবে দেওয়া ভালো হতো?';
  const b=node('button','', 'Save as an example');const sm=node('small','', 'Future similar replies will follow this style, not copy it word for word.');f.append(ta,b,sm);d.append(sum,f);box.appendChild(d)}
 function addMessage(m,csrf){const box=node('div','bubble '+(m.direction==='out'?'out':''));box.dataset.messageId=m.id;box.dataset.messageTime=m.created_at;box.appendChild(node('small','',m.direction==='out'?(m.source==='whatsapp_business_app'?'You · Phone app':'Bot'):'Customer'));
  if(m.quote){const q=node('div','message-quote'),who=node('strong','',m.quote.label),text=node('span','',m.quote.text);q.append(who,text);box.appendChild(q)}
  if(m.image){const img=document.createElement('img');img.className='customer-image';img.src=m.image;img.alt='Customer attachment';img.loading='lazy';box.appendChild(img)}
  if(m.video){const v=node('video','customer-video');v.controls=true;v.preload='metadata';v.src=m.video;box.appendChild(v)}if(m.direction==='out'){const d=node('span','delivery-status',m.delivery||'Status unavailable');d.dataset.deliveryId=m.id;box.appendChild(d)}const p=linkedParagraph(m.body),time=node('time','',m.display_time||m.created_at);box.append(p,time);if(m.can_reply){const rb=node('button','message-reply-button','↩ Reply');rb.type='button';rb.dataset.replyMessageId=m.id;box.appendChild(rb)}if(m.direction==='out'&&m.feedback!==false)feedback(box,m,csrf);const key=String(m.created_at||'')+'|'+String(m.id).padStart(20,'0');box.dataset.sortKey=key;const before=Array.from(stream.children).find(x=>{const xKey=(x.dataset.messageTime||'')+'|'+String(x.dataset.messageId||'').padStart(20,'0');return xKey>key});stream.insertBefore(box,before||null);last=Math.max(last,Number(m.id)||0)}
 function updateList(rows){const frag=document.createDocumentFragment();rows.forEach(c=>{const a=document.createElement('a');a.href='?view=conversations&conv='+c.id+'&q='+encodeURIComponent(new URLSearchParams(location.search).get('q')||'');if(c.id===conv)a.className='current';const name=node('span','conversation-name');name.appendChild(node('strong','',c.name));if(c.unread>0)name.appendChild(node('b','unread-badge',String(c.unread)));a.appendChild(name);a.appendChild(node('small','',c.last_at+(c.handoff?' · Human takeover':'')));frag.appendChild(a)});list.replaceChildren(frag)}
 async function poll(){if(busy||document.hidden)return;busy=true;try{const near=window.innerHeight+window.scrollY>=document.body.offsetHeight-260;const r=await fetch('?realtime=1&conv='+conv+'&after='+last+'&q='+encodeURIComponent(new URLSearchParams(location.search).get('q')||''),{cache:'no-store',credentials:'same-origin'});if(!r.ok)throw Error();const data=await r.json();updateList(data.conversations||[]);(data.deletions||[]).forEach(d=>{const bubble=stream.querySelector('[data-message-id="'+d.id+'"]');if(!bubble||bubble.dataset.deleted==='1')return;bubble.dataset.deleted='1';bubble.querySelectorAll('p,img,video,.message-quote,.message-reply-button,.reply-feedback').forEach(el=>el.remove());bubble.insertBefore(node('p','','[Message deleted]'),bubble.querySelector('time'));});(data.delivery||[]).forEach(d=>{const el=document.querySelector('[data-delivery-id="'+d.id+'"]');if(el){el.textContent=d.label;el.classList.toggle('seen',d.label.includes('Seen'))}});if(navUnread){const n=Number(data.unread_total)||0;navUnread.textContent=String(n);navUnread.hidden=n===0;}(data.messages||[]).forEach(m=>addMessage(m,data.csrf));if(data.messages&&data.messages.length){if(near)window.scrollTo({top:document.body.scrollHeight,behavior:'smooth'});else status.textContent='● New message'}else status.textContent='● Live'}catch(e){status.textContent='● Reconnecting…'}finally{busy=false}}
 const replyForm=document.getElementById('direct-reply-form'),replyBox=document.getElementById('direct-reply-message'),pauseSend=document.getElementById('pause-send'),normalSend=document.getElementById('normal-send'),replyModeHelp=document.getElementById('reply-mode-help'),replyLearnOption=document.getElementById('reply-learn-option'),replyMessageId=document.getElementById('reply-message-id'),replyPreview=document.getElementById('composer-reply-preview'),replyPreviewText=document.getElementById('composer-reply-text'),cancelMessageReply=document.getElementById('cancel-message-reply');
 if(replyForm&&replyBox&&pauseSend){
  const syncReplyMode=()=>{const exact=replyForm.querySelector('input[name="reply_mode"]:checked')?.value==='exact';pauseSend.textContent=exact?'Send exactly & pause bot':'Polish, send & pause bot';if(normalSend)normalSend.textContent=exact?'Send exactly':'Polish & send';if(replyModeHelp)replyModeHelp.textContent=exact?'Press Enter to send these exact words, teach the bot and pause automatic replies. Use Shift + Enter for a new line.':'Press Enter to polish, send and pause the bot. Use Shift + Enter for a new line.';if(replyLearnOption)replyLearnOption.style.display=exact?'none':''};
  replyForm.querySelectorAll('input[name="reply_mode"]').forEach(r=>r.addEventListener('change',syncReplyMode));syncReplyMode();
  const clearReplyTarget=()=>{replyMessageId.value='';replyPreview.hidden=true;replyPreviewText.textContent=''};
  stream.addEventListener('click',e=>{const button=e.target.closest('.message-reply-button');if(!button)return;const bubble=button.closest('.bubble'),body=bubble?bubble.querySelector(':scope > p'):null;replyMessageId.value=button.dataset.replyMessageId||'';replyPreviewText.textContent=body?body.textContent.trim().slice(0,300):'Customer message';replyPreview.hidden=false;replyBox.focus();replyForm.scrollIntoView({behavior:'smooth',block:'center'})});
  if(cancelMessageReply)cancelMessageReply.addEventListener('click',clearReplyTarget);
  replyBox.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();if(replyForm.reportValidity())replyForm.requestSubmit(pauseSend)}});
  replyForm.addEventListener('submit',async e=>{e.preventDefault();if(replyForm.dataset.sending==='1')return;const submitter=e.submitter||pauseSend,fd=new FormData(replyForm);fd.set('act',submitter.value||'direct_reply_pause');fd.set('_ajax','1');replyForm.dataset.sending='1';replyForm.querySelectorAll('button').forEach(b=>b.disabled=true);status.textContent='● Sending…';
   try{const r=await fetch(location.href,{method:'POST',body:fd,credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest'}}),data=await r.json();if(!r.ok||!data.ok)throw Error(data.error||'Message could not be sent.');replyBox.value='';clearReplyTarget();status.textContent='● Sent';await poll()}
   catch(err){status.textContent='● Send failed';alert(err.message)}finally{replyForm.dataset.sending='0';replyForm.querySelectorAll('button').forEach(b=>b.disabled=false);replyBox.focus()}
  });
 }
 const fileForm=document.getElementById('file-share-form'),fileInput=document.getElementById('share-file-input'),filePreview=document.getElementById('file-preview');let previewUrls=[];
 if(fileForm&&fileInput){fileInput.addEventListener('change',()=>{previewUrls.forEach(u=>URL.revokeObjectURL(u));previewUrls=[];filePreview.replaceChildren();const files=Array.from(fileInput.files||[]);if(files.length>5){alert('Select up to 5 files.');fileInput.value='';filePreview.hidden=true;return}files.forEach(file=>{const item=node('span','file-preview-item'),name=node('small','',file.name);if(file.type.startsWith('image/')){const img=document.createElement('img'),url=URL.createObjectURL(file);previewUrls.push(url);img.src=url;img.alt='Selected image';item.appendChild(img)}else item.appendChild(node('span','file-doc-icon','FILE'));item.appendChild(name);filePreview.appendChild(item)});filePreview.hidden=files.length===0});
  fileForm.addEventListener('submit',async e=>{e.preventDefault();if(fileForm.dataset.sending==='1'||!fileForm.reportValidity())return;const fd=new FormData(fileForm);fd.set('_ajax','1');fileForm.dataset.sending='1';fileForm.querySelectorAll('button,input').forEach(x=>x.disabled=true);status.textContent='● Uploading files…';try{const r=await fetch(location.href,{method:'POST',body:fd,credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest'}}),data=await r.json();if(!r.ok||!data.ok)throw Error(data.error||'Files could not be sent.');fileForm.reset();previewUrls.forEach(u=>URL.revokeObjectURL(u));previewUrls=[];filePreview.replaceChildren();filePreview.hidden=true;status.textContent='● Files sent';await poll()}catch(err){status.textContent='● Upload failed';alert(err.message)}finally{fileForm.dataset.sending='0';fileForm.querySelectorAll('button,input').forEach(x=>x.disabled=false)}});
 }
 setInterval(poll,3000);window.addEventListener('focus',poll);document.addEventListener('visibilitychange',()=>{if(!document.hidden)poll()});
})();
</script><?php endif; ?></body></html>
